// Shader warm-up (ac4 --warm-shaders): compiles the programs listed in the shader manifest
// (data/shader_manifest.txt, tools/shader_manifest.py) into the shader cache before a new
// installation's first run, so their first use does not stall the game (0.1-0.3 s per shader).
// The programs come from the user's own game files at the manifest's positions; the HLSL is
// generated by the same translators with the same inputs as at run time, so the cache keys match.
#include "runtime/gpu/shader_warm.h"

#include <algorithm>
#include <atomic>
#include <chrono>
#include <cstring>
#include <filesystem>
#include <fstream>
#include <map>
#include <sstream>
#include <thread>
#include <vector>

#include "common/crypto.h"
#include "common/file.h"
#include "runtime/config.h"
#include "runtime/gpu/d3d11_device.h"
#include "runtime/gpu/fp_hlsl.h"
#include "runtime/gpu/vp_hlsl.h"
#include "runtime/log.h"

namespace rt::gpu {
namespace {

struct Job {
  bool vertex = false;
  u32 source = 0, offset = 0, size = 0, start = 0;
  FpEnv env;
};

}  // namespace

WarmResult warm_shaders(const std::string& manifest, const std::string& disc_root, const std::string& prepared) {
  WarmResult r;
  std::ifstream in(manifest);
  if (!in) {
    r.error = "no shader manifest at " + manifest;
    return r;
  }
  std::map<u32, std::vector<u8>> files;  // source index -> contents (only sources whose hash matches)
  std::vector<Job> jobs;
  std::string line;
  while (std::getline(in, line)) {
    std::istringstream ls(line);
    std::string kind;
    ls >> kind;
    if (kind.empty() || kind[0] == '#') continue;
    if (kind == "source") {  // "source N disc|prepared RELATIVE-PATH SHA256"
      u32 idx;
      std::string where, rel, sha;
      ls >> idx >> where >> rel >> sha;
      std::filesystem::path p = std::filesystem::path(where == "prepared" ? prepared : disc_root) / rel;
      try {
        std::vector<u8> data = ac4::read_file(p);
        auto h = ac4::crypto::sha256(data.data(), data.size());
        std::string hex;
        for (u8 b : h) hex += ac4::strprintf("%02x", b);
        if (hex == sha) files[idx] = std::move(data);
        else LOG_W("warm", "%s differs from the manifest's version (SHA-256 %s): its programs are skipped", rel.c_str(), hex.c_str());
      } catch (const std::exception& e) {
        LOG_W("warm", "%s: %s", rel.c_str(), e.what());
      }
      continue;
    }
    Job j;
    std::string off, size, tag, val;
    ls >> j.source >> off >> size >> tag >> val;
    j.offset = u32(std::stoul(off, nullptr, 16));
    j.size = u32(std::stoul(size, nullptr, 16));
    if (kind == "vp" && tag == "start") {
      j.vertex = true;
      j.start = u32(std::stoul(val));
    } else if (kind == "fp" && tag == "env" && val.size() == 2 * sizeof(FpEnv)) {
      u8 raw[sizeof(FpEnv)];
      for (size_t i = 0; i < sizeof raw; ++i) raw[i] = u8(std::stoul(val.substr(2 * i, 2), nullptr, 16));
      std::memcpy(&j.env, raw, sizeof raw);
    } else {
      continue;
    }
    jobs.push_back(j);
  }
  r.programs = u32(jobs.size());
  u32 before_compiled, before_cached;
  double before_secs;
  shader_stats(&before_compiled, &before_cached, &before_secs);
  std::atomic<size_t> next{0};
  std::atomic<u32> skipped{0}, failed{0};
  auto worker = [&] {
    for (size_t k; (k = next.fetch_add(1)) < jobs.size();) {
      const Job& j = jobs[k];
      auto f = files.find(j.source);
      if (f == files.end() || u64(j.offset) + j.size > f->second.size()) {
        ++skipped;
        continue;
      }
      const u8* code = f->second.data() + j.offset;
      std::string src;
      const char* target;
      if (j.vertex) {
        if (j.size % 16 || j.start + j.size / 16 > kVpSlots) {
          ++skipped;
          continue;
        }
        std::vector<u32> slots(kVpSlots * 4, 0);
        for (u32 i = 0; i < j.size / 4; ++i) {
          u32 w;
          std::memcpy(&w, code + 4 * i, 4);
          slots[4 * j.start + i] = __builtin_bswap32(w);
        }
        VpInfo info;
        src = vp_to_hlsl(slots.data(), j.start, &info);
        if (!info.error.empty()) {
          ++failed;
          continue;
        }
        target = "vs_5_0";
      } else {
        FpInfo info;
        src = fp_to_hlsl(code, j.size, j.env, &info);
        if (!info.error.empty()) {
          ++failed;
          continue;
        }
        target = "ps_5_0";
      }
      if (cfg().dump_shaders) {  // --dump-shaders: compare with a game run's dumps
        std::filesystem::path dir = std::filesystem::path(cfg().run_dir) / "warm_shaders";
        std::error_code ec;
        std::filesystem::create_directories(dir, ec);
        ac4::write_file((dir / ac4::strprintf("%s_%u_%x_%zu.hlsl", j.vertex ? "vp" : "fp", j.source, j.offset, k)).string(),
                         std::vector<u8>(src.begin(), src.end()));
      }
      if (ID3DBlob* b = compile_hlsl(src, "main", target)) b->Release();
      else ++failed;
    }
  };
  auto t0 = std::chrono::steady_clock::now();
  u32 n = std::max(1u, std::thread::hardware_concurrency() > 2 ? std::thread::hardware_concurrency() - 1 : 1u);
  std::vector<std::thread> pool;
  for (u32 i = 0; i < n; ++i) pool.emplace_back(worker);
  for (auto& t : pool) t.join();
  r.seconds = std::chrono::duration<double>(std::chrono::steady_clock::now() - t0).count();
  u32 compiled, cached;
  double secs;
  shader_stats(&compiled, &cached, &secs);
  r.compiled = compiled - before_compiled;
  r.cached = cached - before_cached;
  r.skipped = skipped;
  r.failed = failed;
  r.threads = n;
  return r;
}

}  // namespace rt::gpu
